        pose = {"t": z["pose_t"], "world": z["pose_world"], "vis": z["pose_vis"]}
    return {"path": path, "meta": meta, "imu": imu, "pose": pose}


def block_paths(root=DATA_DIR):
    out = []
    if not os.path.isdir(root):
